"""Tests for safety_analysis_spn."""

import json
import os
import tempfile
import unittest

from lobster.common.errors import Message_Handler
from lobster.common.io import lobster_read, lobster_write
from lobster.common.items import Requirement, Tracing_Tag
from lobster.common.location import File_Reference

from safety_analysis_spn import ConversionError, convert, load_fault_ids, load_root_causes, main

SPEC = """\
package ScoreReq

enum Guideword "Guide words" {
    // MF_01_01: message is not received
    // EX_01_04: loss of execution [shared with Execution]
    LossOfFunction "Absent."

    // Note: also MF_01_02
    // MF_01_05: message is corrupted
    Corrupted "Corrupted."
}
"""

STUB = """\
// GENERATED by puml_cli from FTA diagrams -- do not edit
package Fmea_fta

import Fmea
import ScoreReq

// fta.puml:5
ScoreReq.RootCause CallNotIssued {
  title = "Call is \\"not\\" issued"
  diagram = "fta.puml"
  line = 5
  failure_modes = [Fmea.comp_saf_fmea__x__no_return]
}

// fta.puml:6
ScoreReq.RootCause Unknown {
  title = "Names an unknown failure mode"
  diagram = "fta.puml"
  line = 6
  failure_modes = [Fmea.comp_saf_fmea__x__missing, Other.comp_saf_fmea__x__no_return]
}
"""


def _fmea(need_id, **fields):
    need = {
        "type": "comp_saf_fmea",
        "title": need_id,
        "content": "Rationale.",
        "version": 1,
        "status": "valid",
        "docname": "fmea",
        "lineno": 3,
        "violates": ["comp_arc_sta__x__x[version==1]"],
        "fault_id": "MF_01_01",
        "failure_effect": "Effect.",
        "sufficient": "yes",
    }
    need.update(fields)
    return need


NEEDS = {
    "real_arc_int__x__api": {"type": "real_arc_int", "title": "Api"},
    "real_arc_int_op__x__set": {
        "type": "real_arc_int_op",
        "title": "Set",
        "included_by": ["real_arc_int__x__api[version==1]"],
    },
    "real_arc_int_op__x__gone": {
        "type": "real_arc_int_op",
        "title": "Gone",
        "included_by": ["real_arc_int__x__api[version==1]"],
    },
    "comp_saf_fmea__x__no_return": _fmea(
        "comp_saf_fmea__x__no_return",
        violates=["comp_arc_sta__x__x[version==1]", "real_arc_int_op__x__set[version==1]", "real_arc_int_op__x__gone"],
        fault_id="MF_01_01,EX_01_04",
        mitigated_by=["aou_req__x__use[version==2]", "aou_req__platform__other[version==1]"],
    ),
    "comp_saf_fmea__x__open": _fmea("comp_saf_fmea__x__open", sufficient="no"),
    "comp_saf_fmea__x__invalid": _fmea("comp_saf_fmea__x__invalid", status="invalid", fault_id="UNKNOWN"),
    "comp_saf_fmea__y__other": _fmea("comp_saf_fmea__y__other", violates=["comp_arc_sta__y__y"]),
}


class SafetyAnalysisSpnTest(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.spec = self._write("model.rsl", SPEC)
        self.stub = self._write("fta_events.trlc", STUB)
        self.needs = self._needs(NEEDS)
        self.api = self._lobster(
            "api.lobster",
            [("x_api.Api_Set", None, "['bool x::Api::Set(value : T)', 'bool x::Api::Set(value : T, n : int)']")],
        )
        self.measures = self._lobster("aou.lobster", [("aou_req__x__use", 2, "Use it.")])

    def _write(self, name, text):
        path = os.path.join(self.tmp.name, name)
        with open(path, "w", encoding="utf-8") as f:
            f.write(text)
        return path

    def _needs(self, needs):
        return self._write("needs.json", json.dumps({"current_version": "1", "versions": {"1": {"needs": needs}}}))

    def _lobster(self, name, items):
        path = os.path.join(self.tmp.name, name)
        reqs = [
            Requirement(Tracing_Tag("req", tag, version), File_Reference("x"), "TRLC", "Req", tag, text, None)
            for tag, version, text in items
        ]
        with open(path, "w", encoding="utf-8") as f:
            lobster_write(f, Requirement, "test", reqs)
        return path

    def _convert(self, needs=None, fta_events=None):
        return convert(
            [needs or self.needs], "comp_arc_sta__x__x", "Fmea", [self.spec], [self.api], fta_events, [self.measures]
        )

    @staticmethod
    def _refs(item):
        return sorted(str(ref) for ref in item.unresolved_references)

    def test_fault_ids_come_from_the_guideword_enum(self):
        self.assertEqual(load_fault_ids([self.spec]), {"MF_01_01", "EX_01_04", "MF_01_05"})

    def test_fault_ids_of_the_score_requirements_model(self):
        spec = [p for p in os.environ.get("SCORE_REQUIREMENTS_MODEL", "").split() if p.endswith(".rsl")]
        if not spec:
            self.skipTest("SCORE_REQUIREMENTS_MODEL is not set")
        fault_ids = load_fault_ids(spec)
        self.assertEqual(len(fault_ids), 15)
        self.assertIn("MF_01_01", fault_ids)
        self.assertIn("EX_01_06", fault_ids)

    def test_unknown_fault_id_fails(self):
        needs = self._needs({"comp_saf_fmea__x__bad": _fmea("comp_saf_fmea__x__bad", fault_id="MF_01_01,XX_99_99")})
        with self.assertRaisesRegex(ConversionError, "XX_99_99"):
            self._convert(needs)

    def test_selects_the_valid_failure_modes_of_the_architecture_element(self):
        result = self._convert()
        self.assertEqual(
            [item.name for item in result.failure_modes],
            ["Fmea.comp_saf_fmea__x__no_return", "Fmea.comp_saf_fmea__x__open"],
        )

    def test_violated_operations_become_api_references(self):
        no_return = self._convert().failure_modes[0]
        # Gone has no API method: LOBSTER reports the reference as unknown.
        self.assertEqual(self._refs(no_return), ["req Api::Gone", "req x_api.Api_Set"])

    def test_root_causes_from_the_generated_stub(self):
        package, root_causes = load_root_causes(self.stub)
        self.assertEqual(package, "Fmea_fta")
        self.assertEqual(root_causes[0].title, 'Call is "not" issued')
        self.assertEqual(root_causes[0].line, 5)
        result = self._convert(fta_events=self.stub)
        self.assertEqual(
            {item.name: self._refs(item) for item in result.root_causes},
            {
                "Fmea_fta.CallNotIssued": ["req Fmea.comp_saf_fmea__x__no_return"],
                "Fmea_fta.Unknown": ["req Fmea.comp_saf_fmea__x__missing", "req Other.comp_saf_fmea__x__no_return"],
            },
        )

    def test_sufficient_failure_mode_assesses_its_root_causes(self):
        result = self._convert(fta_events=self.stub)
        self.assertEqual([item.name for item in result.assessments], ["Fmea.comp_saf_fmea__x__no_return.assessment"])
        assessment = result.assessments[0]
        self.assertEqual(assessment.tag.version, "1")
        # The platform AoU is not a measure of the analysis.
        self.assertEqual(self._refs(assessment), ["req Fmea_fta.CallNotIssued", "req aou_req__x__use@2"])

    def test_no_fault_trees_no_assessments(self):
        result = self._convert()
        self.assertEqual(result.root_causes, [])
        self.assertEqual(result.assessments, [])

    def test_main_writes_the_lobster_files_and_the_page(self):
        out = {name: os.path.join(self.tmp.name, name) for name in ["fm", "rc", "as", "rst"]}
        args = [self.needs, "--arch-id", "comp_arc_sta__x__x", "--package", "Fmea", "--spec", self.spec]
        args += ["--api", self.api, "--measures", self.measures, "--fta-events", self.stub, "--diagram", "fta.puml"]
        args += ["--failuremodes-out", out["fm"], "--root-causes-out", out["rc"], "--assessments-out", out["as"]]
        args += ["--rst-out", out["rst"], "--title", "x_safety_analysis"]
        self.assertEqual(main(args), 0)
        counts = {}
        for name in ["fm", "rc", "as"]:
            items = {}
            lobster_read(Message_Handler(), out[name], "level", items)
            counts[name] = len(items)
        self.assertEqual(counts, {"fm": 2, "rc": 2, "as": 1})
        with open(out["rst"], encoding="utf-8") as f:
            page = f.read()
        self.assertTrue(page.startswith("x_safety_analysis\n================="))
        self.assertIn(".. uml:: fta.puml", page)

    def test_main_fails_on_an_unknown_fault_id(self):
        needs = self._needs({"comp_saf_fmea__x__bad": _fmea("comp_saf_fmea__x__bad", fault_id="XX_99_99")})
        out = os.path.join(self.tmp.name, "out")
        args = [needs, "--arch-id", "comp_arc_sta__x__x", "--package", "Fmea", "--spec", self.spec]
        args += ["--failuremodes-out", out, "--root-causes-out", out, "--assessments-out", out, "--rst-out", out]
        self.assertEqual(main(args), 1)


if __name__ == "__main__":
    unittest.main()
